    public long jobId;
    public int taskIndex;
    public long machineId;
    public int eventType;
    public String userName;
    public int schedulingClass;
    public int priority;
    public Double cpuRequest;
    public Double ramRequest;
    public Double diskRequest;
    public Boolean differentMachineConstraint;

    public TaskEvent() {}

    public TaskEvent(long timestamp, String missingInfo, long jobId, int taskIndex, long machineId, int eventType, String userName, int schedulingClass, int priority, Double cpuRequest, Double ramRequest, Double diskRequest, Boolean differentMachineConstraint) {
        this.timestamp = timestamp;
