        this.cpuRequest = cpuRequest;
        this.ramRequest = ramRequest;
        this.diskRequest = diskRequest;
        this.differentMachineConstraint = differentMachineConstraint;
    }

    public static TaskEvent fromString(String line) {
        String[] tokens = line.split(",", -1);
        if (tokens.length < 13) return null;
        return new TaskEvent(
                tokens[0].isEmpty() ? 0 : Long.parseLong(tokens[0]),
                tokens[1],
                tokens[2].isEmpty() ? 0 : Long.parseLong(tokens[2]),
                tokens[3].isEmpty() ? 0 : Integer.parseInt(tokens[3]),
                tokens[4].isEmpty() ? 0 : Long.parseLong(tokens[4]),
                tokens[5].isEmpty() ? 0 : Integer.parseInt(tokens[5]),
                tokens[6],
                tokens[7].isEmpty() ? 0 : Integer.parseInt(tokens[7]),
                tokens[8].isEmpty() ? 0 : Integer.parseInt(tokens[8]),
                tokens[9].isEmpty() ? 0.0 : Double.parseDouble(tokens[9]),
                tokens[10].isEmpty() ? 0.0 : Double.parseDouble(tokens[10]),
                tokens[11].isEmpty() ? 0.0 : Double.parseDouble(tokens[11]),
                tokens[12].equals("1")
