package clusterdata.query;

import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import org.apache.flink.api.common.RuntimeExecutionMode;
import org.apache.flink.api.common.eventtime.SerializableTimestampAssigner;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.functions.MapFunction;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.windowing.assigners.EventTimeSessionWindows;
import org.apache.flink.streaming.api.windowing.time.Time;

import java.time.Duration;

public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);

        // set up streaming execution environment
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setRuntimeMode(RuntimeExecutionMode.BATCH);
        env.setParallelism(1);

        DataStream<String> taskLines = env.readTextFile(taskInput);

        DataStream<TaskEvent> taskEvents = taskLines
                .map(new MapFunction<String, TaskEvent>() {
                    @Override
                    public TaskEvent map(String value) throws Exception {
                        return TaskEvent.fromString(value);
                    }
                })
                .filter(event -> event != null && event.eventType == 0); // SUBMIT

        WatermarkStrategy<TaskEvent> watermarkStrategy = WatermarkStrategy
                .<TaskEvent>forBoundedOutOfOrderness(Duration.ofSeconds(1))
                .withTimestampAssigner(new SerializableTimestampAssigner<TaskEvent>() {
                    @Override
                    public long extractTimestamp(TaskEvent element, long recordTimestamp) {
                        return element.timestamp / 1000; // micro to milli
                    }
                });

        DataStream<Tuple2<Long, Integer>> sessionCounts = taskEvents
                .assignTimestampsAndWatermarks(watermarkStrategy)
                .keyBy(event -> event.jobId)
                .window(EventTimeSessionWindows.withGap(Time.minutes(10)))
                .apply((Long jobId, org.apache.flink.streaming.api.windowing.windows.TimeWindow window, Iterable<TaskEvent> input, org.apache.flink.util.Collector<Tuple2<Long, Integer>> out) -> {
                    int count = 0;
                    for (TaskEvent event : input) {
                        count++;
                    }
                    out.collect(new Tuple2<>(jobId, count));
                });

        DataStream<Tuple2<Long, Integer>> maxSessions = sessionCounts
                .keyBy(t -> t.f0)
                .reduce((t1, t2) -> t1.f1 >= t2.f1 ? t1 : t2);

        maxSessions.map(new MapFunction<Tuple2<Long, Integer>, String>() {
            @Override
            public String map(Tuple2<Long, Integer> value) throws Exception {
                return "(" + value.f0 + "," + value.f1 + ")";
            }
        }).writeAsText(outputPath).setParallelism(1);

        env.execute("LongestSessionPerJob");
    }

}

package clusterdata.sources;

import clusterdata.datatypes.TaskEvent;
import org.apache.flink.streaming.api.functions.source.SourceFunction;

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.InputStreamReader;
import java.util.zip.GZIPInputStream;

public class TaskEventSource implements SourceFunction<TaskEvent> {
    private final String filePath;

    public TaskEventSource(String filePath) {
        this.filePath = filePath;
    }

    @Override
    public void run(SourceContext<TaskEvent> ctx) throws Exception {
        if (filePath == null) return;
        try (GZIPInputStream gzipStream = new GZIPInputStream(new FileInputStream(filePath));
             BufferedReader reader = new BufferedReader(new InputStreamReader(gzipStream))) {
            String line;
            while ((line = reader.readLine()) != null) {
                TaskEvent event = TaskEvent.fromString(line);
                if (event != null) {
                    ctx.collect(event);
                }
            }
        }
    }

    @Override
    public void cancel() {
    }
}

